SourceCode.Declaration:
/// <summary>
/// Counting task operations that sit beside HSMobileOpsCountingService's DMF export/import:
/// claims (claimJournal / heartbeatClaim / releaseJournal), journal state, and the DIRECT
/// transfer mode (getJournalLines / submitCounts) used for small journals.
///
/// The app only renders and captures. Every rule - claim TTL, who may hold which range, when a
/// claim is lost, which transfer mode a journal uses, how a direct count is written to
/// InventJournalTrans - belongs here, in X++. The operations still marked TODO below validate
/// their request and the journal's state for real, then return NOT_IMPLEMENTED. The app treats
/// NOT_IMPLEMENTED as "feature not available on this server" and keeps every local count.
///
/// Claims: one row per journal in HSMobileOpsLineClaim (ProcessType COUNT, LineNumber 0), held
/// by one user on one device - the same login on two handhelds is two holders. A claim lives
/// claimTtlSeconds past its last heartbeat; the app heartbeats every claimHeartbeatSeconds.
/// The token is the claim row's RecId, checked together with the user and device. Submits
/// (submitCounts here, importCounts on HSMobileOpsCountingService) are refused with CLAIM_LOST
/// while another device holds a live claim, so a second device can no longer overwrite counts.
///
/// Registered as HSMobileOpsCountTaskSvc in HSMobileOpsServiceGroup - needs a full service
/// group build, not a class-only build (see aos/README.md, Installing).
/// </summary>
class HSMobileOpsCountTaskService
{
}

Method.Source:
/// <summary>
/// Claims a journal, or one location range of it, for one user on one device.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountClaimResponse claimJournal(HSMobileOpsCountClaimRequest _request)
{
    HSMobileOpsCountClaimResponse response = new HSMobileOpsCountClaimResponse();
    str                           state;

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId()
        || !_request.parmUserId() || !_request.parmDeviceId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    state = HSMobileOpsCountTaskService::journalState(_request.parmDataAreaId(), _request.parmJournalId());
    if (state != HSMobileOpsCountTaskService::stateOpen())
    {
        response.parmErrorCode(state == HSMobileOpsCountTaskService::statePosted() ? 'JOURNAL_POSTED' : 'JOURNAL_NOT_FOUND');
        return response;
    }

    // The whole journal is claimed, except a wall-to-wall journal: there each location is a
    // task, claimed on its own, and several counters work the journal at once.
    changecompany (_request.parmDataAreaId())
    {
        HSMobileOpsLineClaim claim;
        utcdatetime          now = DateTimeUtil::utcNow();
        str                  taskError;

        if (HSMobileOpsCountWallToWall::isWallToWall(_request.parmJournalId()))
        {
            if (_request.parmRangeId())
            {
                taskError = HSMobileOpsCountWallToWall::claimTask(_request.parmJournalId(),
                    HSMobileOpsCountWallToWall::locationOfRange(_request.parmRangeId()), _request.parmUserId(), response);
                if (taskError)
                {
                    response.parmErrorCode(taskError);
                }
                return response;
            }
            if (HSMobileOpsCountTask::openTasks(_request.parmJournalId()))
            {
                response.parmErrorCode('CHOOSE_RANGE');
                response.parmMessage('Choose a location to count.');
                return response;
            }
            // Every location is complete: second counts and recounts, journal-wide, unlocked.
            response.parmSuccess(true);
            response.parmClaimToken(HSMobileOpsCountWallToWall::taskToken(0));
            response.parmExpiresUtc(DateTimeUtil::maxValue());
            response.parmHeartbeatSeconds(HSMobileOpsCountTaskService::claimHeartbeatSeconds());
            return response;
        }

        try
        {
            ttsbegin;
            select forUpdate firstOnly claim
                where claim.ProcessType == HSMobileOpsCountTaskService::claimProcess()
                   && claim.SourceId    == _request.parmJournalId()
                   && claim.LineNumber  == 0;

            if (claim.RecId && claim.ClaimExpiresUtc > now
                && !HSMobileOpsCountTaskService::isClaimHolder(claim, _request.parmUserId(), _request.parmDeviceId()))
            {
                ttscommit;
                response.parmErrorCode('CLAIMED_BY_OTHER');
                response.parmClaimedBy(HSMobileOpsCountTaskService::claimedByLabel(claim, _request.parmDeviceId()));
                response.parmExpiresUtc(claim.ClaimExpiresUtc);
                return response;
            }

            if (!claim.RecId)
            {
                claim.clear();
                claim.ProcessType = HSMobileOpsCountTaskService::claimProcess();
                claim.SourceId    = _request.parmJournalId();
                claim.LineNumber  = 0;
            }
            claim.ClaimedByUserName    = _request.parmUserId();
            claim.ClaimedByDisplayName = HSMobileOpsUser::find(_request.parmUserId()).DisplayName;
            claim.DeviceId             = _request.parmDeviceId();
            claim.ClaimedAtUtc         = now;
            claim.ClaimExpiresUtc      = DateTimeUtil::addSeconds(now, HSMobileOpsCountTaskService::claimTtlSeconds());
            if (claim.RecId)
            {
                claim.update();
            }
            else
            {
                claim.insert();
            }
            ttscommit;
        }
        catch (Exception::DuplicateKeyException)
        {
            // Two devices claimed the same journal at the same moment; the other one won.
            response.parmErrorCode('CLAIMED_BY_OTHER');
            return response;
        }
        catch (Exception::UpdateConflict)
        {
            response.parmErrorCode('CLAIMED_BY_OTHER');
            return response;
        }

        HSMobileOpsCountTaskService::grantClaim(response, claim);
    }
    return response;
}

/// <summary>
/// Extends a claim's expiry. CLAIM_LOST / CLAIM_EXPIRED when the token is no longer valid.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountClaimResponse heartbeatClaim(HSMobileOpsCountClaimTokenRequest _request)
{
    HSMobileOpsCountClaimResponse response = new HSMobileOpsCountClaimResponse();

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId() || !_request.parmClaimToken())
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // An expired claim that nobody has taken since is still this holder's: it is renewed,
    // not refused - the device was only out of reach for a while.
    changecompany (_request.parmDataAreaId())
    {
        HSMobileOpsLineClaim claim;
        utcdatetime          now = DateTimeUtil::utcNow();
        HSMobileOpsCountTask task;

        if (strStartsWith(_request.parmClaimToken(), 'W2W-'))
        {
            task = HSMobileOpsCountWallToWall::taskOfToken(_request.parmClaimToken());
            if (task.RecId && task.Status == HSMobileOpsCountTaskStatus::InProgress && task.AssignedUserId != _request.parmUserId())
            {
                response.parmErrorCode('CLAIM_LOST');
                response.parmClaimedBy(task.AssignedUserId);
                return response;
            }
            response.parmSuccess(true);
            response.parmClaimToken(_request.parmClaimToken());
            response.parmExpiresUtc(DateTimeUtil::maxValue());
            response.parmHeartbeatSeconds(HSMobileOpsCountTaskService::claimHeartbeatSeconds());
            return response;
        }

        ttsbegin;
        select forUpdate firstOnly claim
            where claim.ProcessType == HSMobileOpsCountTaskService::claimProcess()
               && claim.SourceId    == _request.parmJournalId()
               && claim.LineNumber  == 0;

        if (!claim.RecId || int642Str(claim.RecId) != _request.parmClaimToken())
        {
            ttscommit;
            response.parmErrorCode('CLAIM_EXPIRED');
            return response;
        }
        if (!HSMobileOpsCountTaskService::isClaimHolder(claim, _request.parmUserId(), _request.parmDeviceId()))
        {
            ttscommit;
            if (claim.ClaimExpiresUtc > now)
            {
                response.parmErrorCode('CLAIM_LOST');
                response.parmClaimedBy(HSMobileOpsCountTaskService::claimedByLabel(claim, _request.parmDeviceId()));
            }
            else
            {
                response.parmErrorCode('CLAIM_EXPIRED');
            }
            return response;
        }
        claim.ClaimExpiresUtc = DateTimeUtil::addSeconds(now, HSMobileOpsCountTaskService::claimTtlSeconds());
        claim.update();
        ttscommit;

        HSMobileOpsCountTaskService::grantClaim(response, claim);
    }
    return response;
}

/// <summary>
/// Releases a claim - called by the app after End count succeeds. Releasing a claim that is
/// already gone is a success, not an error.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountClaimResponse releaseJournal(HSMobileOpsCountClaimTokenRequest _request)
{
    HSMobileOpsCountClaimResponse response = new HSMobileOpsCountClaimResponse();

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId() || !_request.parmClaimToken())
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // Only the holder's own claim is removed; someone else's is left to speak for itself. The
    // device and the claim's token are enough - no user: End count's submit can run in the
    // background before anyone has signed in again (11 Oct: the release was sent with no
    // user, refused, and the claim stayed until it expired).
    changecompany (_request.parmDataAreaId())
    {
        HSMobileOpsLineClaim claim;

        if (strStartsWith(_request.parmClaimToken(), 'W2W-'))
        {
            HSMobileOpsCountWallToWall::releaseTask(_request.parmClaimToken(), _request.parmUserId());
            response.parmSuccess(true);
            return response;
        }

        ttsbegin;
        select forUpdate firstOnly claim
            where claim.ProcessType == HSMobileOpsCountTaskService::claimProcess()
               && claim.SourceId    == _request.parmJournalId()
               && claim.LineNumber  == 0;
        if (claim.RecId && int642Str(claim.RecId) == _request.parmClaimToken()
            && _request.parmDeviceId() && claim.DeviceId == _request.parmDeviceId())
        {
            claim.delete();
        }
        ttscommit;
    }
    response.parmSuccess(true);
    return response;
}

/// <summary>The store's active bins. None means the store counts by location alone.</summary>
public HSMobileOpsCountBinResponse getCountBins(HSMobileOpsCountBinRequest _request)
{
    HSMobileOpsCountBinResponse response = new HSMobileOpsCountBinResponse();
    HSMobileOpsCountBin         bin;
    HSMobileOpsCountBinRow      row;
    List                        rows = new List(Types::Class);

    response.parmSuccess(false);
    response.parmBins(rows);
    if (!_request || !_request.parmDataAreaId() || !_request.parmWarehouseId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        while select BinId, Description, WMSLocationId from bin
            order by BinId
            where bin.InventLocationId == _request.parmWarehouseId()
               && bin.Active           == NoYes::Yes
        {
            row = new HSMobileOpsCountBinRow();
            row.parmBinId(bin.BinId);
            row.parmDescription(bin.Description);
            row.parmLocationId(bin.WMSLocationId);
            rows.addEnd(row);
        }
    }
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// A supervisor adds a bin found on the floor to the store's list, or wakes one up that was
/// switched off. Everyone else is refused: a typo must not become a bin.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountBinResponse addCountBin(HSMobileOpsCountBinRequest _request)
{
    HSMobileOpsCountBinResponse response = new HSMobileOpsCountBinResponse();
    HSMobileOpsCountBin         bin;
    HSMobileOpsCountBinRow      row;
    List                        rows = new List(Types::Class);
    str                         binId;

    response.parmSuccess(false);
    response.parmBins(rows);
    binId = _request ? strUpr(strLRTrim(_request.parmBinId())) : '';
    if (!_request || !_request.parmDataAreaId() || !_request.parmWarehouseId() || !binId || strLen(binId) > 20
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('A bin needs a store and a name of up to 20 characters.');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        if (!HSMobileOpsCountDualEngine::isSupervisor(HSMobileOpsUser::find(_request.parmUserId())))
        {
            response.parmErrorCode('NOT_SUPERVISOR');
            response.parmMessage('Only a supervisor can add a bin.');
            return response;
        }
        if (!InventLocation::find(_request.parmWarehouseId()).RecId)
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage(strFmt('No store %1', _request.parmWarehouseId()));
            return response;
        }
        try
        {
            ttsbegin;
            bin = HSMobileOpsCountBin::find(_request.parmWarehouseId(), binId, true);
            if (bin.RecId)
            {
                if (!bin.Active)
                {
                    bin.Active = NoYes::Yes;
                    bin.update();
                }
            }
            else
            {
                bin.initValue();
                bin.InventLocationId = _request.parmWarehouseId();
                bin.BinId            = binId;
                // Added while counting a location: the bin is in it.
                bin.WMSLocationId    = strUpr(strLRTrim(_request.parmLocationId()));
                bin.CreatedByUser    = _request.parmUserId();
                bin.insert();
            }
            ttscommit;
        }
        catch (Exception::DuplicateKeyException)
        {
            // Someone added the same bin at the same moment: it is there, which is the point.
            response.parmMessage('');
        }
    }
    row = new HSMobileOpsCountBinRow();
    row.parmBinId(binId);
    row.parmLocationId(bin.WMSLocationId);
    rows.addEnd(row);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// What this counter counted per bin, for the lines sent: a record beside the count itself. A
/// line's rows are replaced, so a corrected count or a resend leaves no stale bin behind.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountBinResponse submitBinCounts(HSMobileOpsCountBinLinesRequest _request)
{
    HSMobileOpsCountBinResponse   response = new HSMobileOpsCountBinResponse();
    HSMobileOpsCountBinLine       binLine;
    InventJournalTrans            journalTrans;
    InventDim                     inventDim;
    Set                           replaced = new Set(Types::Real);
    Newtonsoft.Json.Linq.JArray   rows;
    Newtonsoft.Json.Linq.JObject  row;
    real                          lineNum;
    int                           i;
    int                           accepted;

    response.parmSuccess(false);
    response.parmBins(new List(Types::Class));
    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId() || !_request.parmUserId() || !_request.parmRowsJson()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    try
    {
        rows = Newtonsoft.Json.Linq.JArray::Parse(_request.parmRowsJson());
    }
    catch (Exception::CLRError)
    {
        response.parmErrorCode('INVALID_REQUEST');
        response.parmMessage('The counts per bin could not be read.');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        try
        {
            ttsbegin;
            for (i = 0; rows != null && i < rows.get_Count(); i++)
            {
                row     = rows.get_Item(i);
                lineNum = HSMobileOpsCountTaskService::jsonNumber(row, 'LineNumber');
                if (!replaced.in(lineNum))
                {
                    replaced.add(lineNum);
                    delete_from binLine
                        where binLine.JournalId == _request.parmJournalId()
                           && binLine.LineNum   == lineNum
                           && binLine.UserId    == _request.parmUserId();
                }
                journalTrans.clear();
                select firstOnly ItemId from journalTrans
                    where journalTrans.JournalId == _request.parmJournalId()
                       && journalTrans.LineNum   == lineNum
                    join wMSLocationId, inventBatchId from inventDim
                        where inventDim.inventDimId == journalTrans.InventDimId;
                binLine.clear();
                binLine.JournalId       = _request.parmJournalId();
                binLine.LineNum         = lineNum;
                binLine.UserId          = _request.parmUserId();
                binLine.BinId           = HSMobileOpsCountTaskService::jsonText(row, 'BinId');
                binLine.CountedQty      = HSMobileOpsCountTaskService::jsonNumber(row, 'Quantity');
                binLine.ItemId          = journalTrans.ItemId;
                binLine.WMSLocationId   = inventDim.wMSLocationId;
                binLine.InventBatchId   = inventDim.inventBatchId;
                binLine.CountedDateTime = DateTimeUtil::utcNow();
                binLine.SubmissionId    = _request.parmSubmissionId();
                binLine.insert();
                accepted++;
            }
            ttscommit;
        }
        catch (Exception::DuplicateKeyException)
        {
            response.parmErrorCode('RETRY');
            return response;
        }
        catch (Exception::Deadlock)
        {
            response.parmErrorCode('RETRY');
            return response;
        }
    }
    response.parmAccepted(accepted);
    response.parmSuccess(true);
    return response;
}

private static str jsonText(Newtonsoft.Json.Linq.JObject _row, str _property)
{
    Newtonsoft.Json.Linq.JToken token = _row == null ? null : _row.get_Item(_property);

    return token == null ? '' : token.ToString();
}

private static real jsonNumber(Newtonsoft.Json.Linq.JObject _row, str _property)
{
    str value = HSMobileOpsCountTaskService::jsonText(_row, _property);

    return value ? str2num(value) : 0;
}

/// <summary>
/// OPEN, POSTED or NOT_FOUND. The app calls this before reopening a submitted journal on the
/// device: a journal posted in D365FO must not be reopened.
/// </summary>
public HSMobileOpsCountJournalStateResponse getJournalState(HSMobileOpsCountJournalStateRequest _request)
{
    HSMobileOpsCountJournalStateResponse response = new HSMobileOpsCountJournalStateResponse();

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    response.parmState(HSMobileOpsCountTaskService::journalState(_request.parmDataAreaId(), _request.parmJournalId()));
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// A small journal's lines, for DIRECT transfer mode - no DMF round trip. Blind: no on-hand,
/// counted or variance quantity is returned. Refuses a journal over maxDirectLines(); those
/// belong on the DMF path.
/// </summary>
public HSMobileOpsCountDirectLinesResponse getJournalLines(HSMobileOpsCountDirectLinesRequest _request)
{
    HSMobileOpsCountDirectLinesResponse response = new HSMobileOpsCountDirectLinesResponse();
    HSMobileOpsCountDirectLineRow       row;
    List                                lines = new List(Types::Class);
    InventJournalTrans                  inventJournalTrans;
    InventDim                           inventDim;
    str                                 state;
    str                                 locationFrom;
    str                                 locationTo;
    int                                 lineCount;

    response.parmSuccess(false);
    response.parmLines(lines);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    state = HSMobileOpsCountTaskService::journalState(_request.parmDataAreaId(), _request.parmJournalId());
    if (state != HSMobileOpsCountTaskService::stateOpen())
    {
        response.parmErrorCode(state == HSMobileOpsCountTaskService::statePosted() ? 'JOURNAL_POSTED' : 'JOURNAL_NOT_FOUND');
        return response;
    }

    // TODO (X++ owner): when claims exist, validate ClaimToken and take the range from the
    // claim rather than from the request.
    locationFrom = _request.parmLocationFrom();
    locationTo   = _request.parmLocationTo();

    changecompany (_request.parmDataAreaId())
    {
        if (HSMobileOpsCountDualEngine::isDual(_request.parmJournalId()))
        {
            HSMobileOpsCountDualEngine::journalLines(_request, response);
            return response;
        }

        while select LineNum, ItemId from inventJournalTrans
            order by LineNum
            where inventJournalTrans.JournalId == _request.parmJournalId()
            join InventSiteId, InventLocationId, wMSLocationId, inventBatchId, inventSerialId,
                 configId, InventSizeId, InventColorId, InventStyleId from inventDim
                where inventDim.InventDimId == inventJournalTrans.InventDimId
        {
            if (locationFrom && inventDim.wMSLocationId < locationFrom)
            {
                continue;
            }
            if (locationTo && inventDim.wMSLocationId > locationTo)
            {
                continue;
            }

            lineCount++;
            if (lineCount > HSMobileOpsCountTaskService::maxDirectLines())
            {
                response.parmLines(new List(Types::Class));
                response.parmErrorCode('TOO_MANY_LINES');
                return response;
            }

            row = new HSMobileOpsCountDirectLineRow();
            row.parmLineNumber(inventJournalTrans.LineNum);
            row.parmItemNumber(inventJournalTrans.ItemId);
            row.parmItemName(InventTable::find(inventJournalTrans.ItemId).itemName());
            row.parmSiteId(inventDim.InventSiteId);
            row.parmWarehouseId(inventDim.InventLocationId);
            row.parmLocationId(inventDim.wMSLocationId);
            row.parmBatchId(inventDim.inventBatchId);
            row.parmSerialId(inventDim.inventSerialId);
            row.parmConfigId(inventDim.configId);
            row.parmSizeId(inventDim.InventSizeId);
            row.parmColorId(inventDim.InventColorId);
            row.parmStyleId(inventDim.InventStyleId);
            row.parmPassNumber(1);
            row.parmRecount(false);
            // TODO (X++ owner): location type / owner / verify-only, as getLineAttributes.
            row.parmLocationType('PHYSICAL');
            row.parmOwner('');
            row.parmVerifyOnly(false);
            lines.addEnd(row);
        }
    }

    response.parmLines(lines);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// DIRECT transfer mode: all counted lines of a journal (or claimed range) in one call.
/// SubmissionId is the idempotency key - a repeat of an already-applied SubmissionId must
/// answer Success without applying anything twice.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountDirectSubmitResponse submitCounts(HSMobileOpsCountDirectSubmitRequest _request)
{
    HSMobileOpsCountDirectSubmitResponse response = new HSMobileOpsCountDirectSubmitResponse();
    str                                  state;

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId() || !_request.parmSubmissionId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    state = HSMobileOpsCountTaskService::journalState(_request.parmDataAreaId(), _request.parmJournalId());
    if (state != HSMobileOpsCountTaskService::stateOpen())
    {
        response.parmErrorCode(state == HSMobileOpsCountTaskService::statePosted() ? 'JOURNAL_POSTED' : 'JOURNAL_NOT_FOUND');
        return response;
    }

    // Each counted line's quantity goes on its journal line the way the counting form puts
    // it there - Counted, and modifiedField works out the quantity to adjust. Setting a
    // count is the same however often it is sent, so a repeated SubmissionId changes
    // nothing. A line only marked (no quantity) is left as it is. Refused while another
    // device holds a live claim on the journal; with no claim at all the counts go in.
    str holder = HSMobileOpsCountTaskService::otherClaimHolder(
        _request.parmDataAreaId(), _request.parmJournalId(), _request.parmUserId(), _request.parmDeviceId());
    if (holder)
    {
        response.parmErrorCode('CLAIM_LOST');
        response.parmMessage(strFmt('%1 is being counted by %2', _request.parmJournalId(), holder));
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        List                           lines = _request.parmLines();
        ListEnumerator                 enumerator;
        HSMobileOpsCountDirectCountRow row;
        InventJournalTrans             journalTrans;
        int                            accepted;
        int                            unknown;

        if (HSMobileOpsCountDualEngine::isDual(_request.parmJournalId()))
        {
            HSMobileOpsCountDualEngine::submitCounts(_request, response);
            return response;
        }

        if (!lines || !lines.elements())
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage('No counted lines were sent');
            return response;
        }
        try
        {
            ttsbegin;
            enumerator = lines.getEnumerator();
            while (enumerator.moveNext())
            {
                row = enumerator.current();
                if (row.parmMarkedOnly())
                {
                    continue;
                }
                if (row.parmCountedQuantity() < 0)
                {
                    throw error(strFmt('Line %1: a count cannot be negative', row.parmLineNumber()));
                }
                select forupdate firstonly journalTrans
                    where journalTrans.JournalId == _request.parmJournalId()
                       && journalTrans.LineNum   == row.parmLineNumber();
                if (!journalTrans.RecId)
                {
                    unknown++;
                    continue;
                }
                journalTrans.Counted = row.parmCountedQuantity();
                journalTrans.modifiedField(fieldNum(InventJournalTrans, Counted));
                journalTrans.update();
                accepted++;
            }
            if (unknown && !accepted)
            {
                throw error(strFmt('None of the %1 counted lines is on %2', unknown, _request.parmJournalId()));
            }
            ttscommit;
            response.parmSuccess(true);
            response.parmAcceptedLines(accepted);
            response.parmPassResult('ACCEPTED');
            response.parmMessage(unknown
                ? strFmt('%1 lines counted; %2 are no longer on the journal', accepted, unknown)
                : strFmt('%1 lines counted', accepted));
        }
        catch (Exception::Error)
        {
            response.parmErrorCode('REJECTED');
            response.parmMessage(infolog.text(infologLine()));
        }
    }
    return response;
}

/// <summary>A property of a JSON row as text; blank when missing or null.</summary>
private static str jsonStr(Newtonsoft.Json.Linq.JObject _obj, str _property)
{
    Newtonsoft.Json.Linq.JToken token;

    if (_obj == null)
    {
        return '';
    }
    token = _obj.get_Item(_property);
    if (token == null)
    {
        return '';
    }
    return token.ToString();
}

/// <summary>
/// Unexpected items ("Not on this journal") and verified-empty locations, sent after the
/// counts of the same submission. The app never creates journal lines itself - resolving an
/// exception (create a line, investigate) is the server's or planner's decision.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountExceptionsResponse submitExceptions(HSMobileOpsCountExceptionsRequest _request)
{
    HSMobileOpsCountExceptionsResponse response = new HSMobileOpsCountExceptionsResponse();
    str                                state;

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId() || !_request.parmSubmissionId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    state = HSMobileOpsCountTaskService::journalState(_request.parmDataAreaId(), _request.parmJournalId());
    if (state != HSMobileOpsCountTaskService::stateOpen())
    {
        response.parmErrorCode(state == HSMobileOpsCountTaskService::statePosted() ? 'JOURNAL_POSTED' : 'JOURNAL_NOT_FOUND');
        return response;
    }

    // An unexpected item becomes a line of this journal, the way the counting form adds one
    // (feedback, 12 Oct: "1 unexpected item could not be sent" - this was never built): on
    // the matching stock record, or a new dimension with on-hand 0. A resend sets the same
    // count again rather than adding a second line; items scanned twice in one submission
    // are added together. Empty locations and verified lines need nothing stored.
    // An item with product dimensions cannot be placed - the device does not capture them.
    changecompany (_request.parmDataAreaId())
    {
        System.Object                 parsedObj;
        Newtonsoft.Json.Linq.JArray   jArray;
        Newtonsoft.Json.Linq.JObject  jRow;
        Map                           qtys = new Map(Types::String, Types::Real);
        Map                           samples = new Map(Types::String, Types::Record);
        MapEnumerator                 e;
        HSMobileOpsCountStageLine     counted;
        InventJournalTable            journalTable;
        InventJournalTrans            journalTrans;
        InventJournalTrans            lastTrans;
        InventDim                     inventDim;
        InventDimGroupSetup           dimSetup;
        InventLocationId              store;
        LineNum                       lineNum;
        str                           key;
        str                           skipped;
        int                           i;
        int                           accepted;
        int                           notPlaced;
        boolean                       dual = HSMobileOpsCountDualEngine::isDual(_request.parmJournalId());
        HSMobileOpsCountDualEngine    engine = new HSMobileOpsCountDualEngine();
        boolean                       supervisor = HSMobileOpsCountDualEngine::isSupervisor(HSMobileOpsUser::find(_request.parmUserId()));
        str                           emptyRefusals;

        // Wall-to-wall: "Location is empty" settles the location's lines at 0 and completes it.
        if (HSMobileOpsCountWallToWall::isWallToWall(_request.parmJournalId())
         && _request.parmEmptyLocationsJson() && _request.parmEmptyLocationsJson() != '[]')
        {
            emptyRefusals = HSMobileOpsCountTaskService::confirmEmptyLocations(_request);
        }

        if (!_request.parmExceptionsJson() || _request.parmExceptionsJson() == '[]')
        {
            if (emptyRefusals)
            {
                response.parmErrorCode('EMPTY_REFUSED');
                response.parmMessage(emptyRefusals);
                return response;
            }
            response.parmSuccess(true);
            return response;
        }
        try
        {
            parsedObj = Newtonsoft.Json.Linq.JArray::Parse(_request.parmExceptionsJson());
        }
        catch (Exception::CLRError)
        {
            response.parmErrorCode('INVALID_REQUEST');
            response.parmMessage('The unexpected items could not be read.');
            return response;
        }
        jArray = parsedObj;

        // The journal's store: where its lines are.
        select firstonly InventLocationId from inventDim
            exists join journalTrans
                where journalTrans.InventDimId == inventDim.inventDimId
                   && journalTrans.JournalId   == _request.parmJournalId();
        store = inventDim.InventLocationId;

        for (i = 0; jArray != null && i < jArray.get_Count(); i++)
        {
            jRow = jArray.get_Item(i);
            counted.clear();
            counted.ItemId         = HSMobileOpsCountTaskService::jsonStr(jRow, 'ItemNumber');
            counted.WMSLocationId  = HSMobileOpsCountTaskService::jsonStr(jRow, 'LocationId');
            counted.InventBatchId  = HSMobileOpsCountTaskService::jsonStr(jRow, 'BatchId');
            counted.InventSerialId = HSMobileOpsCountTaskService::jsonStr(jRow, 'SerialId');
            counted.ConfigId       = HSMobileOpsCountTaskService::jsonStr(jRow, 'ConfigId');
            counted.InventSizeId   = HSMobileOpsCountTaskService::jsonStr(jRow, 'SizeId');
            counted.InventColorId  = HSMobileOpsCountTaskService::jsonStr(jRow, 'ColorId');
            counted.InventStyleId  = HSMobileOpsCountTaskService::jsonStr(jRow, 'StyleId');
            if (!counted.ItemId || !InventTable::find(counted.ItemId).RecId)
            {
                notPlaced++;
                skipped += (skipped ? ', ' : '') + (counted.ItemId ? counted.ItemId : '(no item)');
                continue;
            }
            dimSetup = InventDimGroupSetup::newItemId(counted.ItemId);
            // The device sends the variant found (14 Oct); one that is missing cannot be placed.
            if ((dimSetup.isDimensionActive(fieldNum(InventDim, ConfigId)) && !counted.ConfigId)
             || (dimSetup.isDimensionActive(fieldNum(InventDim, InventSizeId)) && !counted.InventSizeId)
             || (dimSetup.isDimensionActive(fieldNum(InventDim, InventColorId)) && !counted.InventColorId)
             || (dimSetup.isDimensionActive(fieldNum(InventDim, InventStyleId)) && !counted.InventStyleId))
            {
                notPlaced++;
                skipped += (skipped ? ', ' : '') + counted.ItemId;
                continue;
            }
            key = strFmt('%1|%2|%3|%4|%5|%6|%7|%8', counted.ItemId, counted.WMSLocationId, counted.InventBatchId, counted.InventSerialId,
                counted.ConfigId, counted.InventSizeId, counted.InventColorId, counted.InventStyleId);
            qtys.insert(key, (qtys.exists(key) ? qtys.lookup(key) : 0)
                + str2num(HSMobileOpsCountTaskService::jsonStr(jRow, 'Quantity')));
            samples.insert(key, counted.data());
        }

        try
        {
            ttsbegin;
            journalTable = InventJournalTable::find(_request.parmJournalId(), true);
            select maxOf(LineNum) from lastTrans where lastTrans.JournalId == journalTable.JournalId;
            lineNum = lastTrans.LineNum;

            e = qtys.getEnumerator();
            while (e.moveNext())
            {
                counted = samples.lookup(e.currentKey());
                journalTrans.clear();
                select forUpdate firstonly journalTrans
                    where journalTrans.JournalId == journalTable.JournalId
                       && journalTrans.ItemId    == counted.ItemId
                    exists join inventDim
                        where inventDim.inventDimId      == journalTrans.InventDimId
                           && inventDim.InventLocationId == store
                           && inventDim.wMSLocationId    == counted.WMSLocationId
                           && inventDim.inventBatchId    == counted.InventBatchId
                           && inventDim.inventSerialId   == counted.InventSerialId
                           && inventDim.configId         == counted.ConfigId
                           && inventDim.InventSizeId     == counted.InventSizeId
                           && inventDim.InventColorId    == counted.InventColorId
                           && inventDim.InventStyleId    == counted.InventStyleId;
                if (!journalTrans.RecId)
                {
                    lineNum++;
                    HSMobileOpsCountControl::addLine(journalTable, lineNum, counted, store, dual ? 0 : e.currentValue());
                    if (dual)
                    {
                        // Found where D365FO holds none: a second counter confirms it.
                        select forUpdate firstOnly journalTrans
                            where journalTrans.JournalId == journalTable.JournalId
                               && journalTrans.LineNum   == lineNum;
                        journalTrans.HSMobileOpsDualRequired = NoYes::Yes;
                        journalTrans.doUpdate();
                    }
                }
                if (dual)
                {
                    // A count like any other, by the dual count rules: never straight onto the line.
                    engine.applyCount(journalTrans, e.currentValue(), _request.parmUserId(), _request.parmDeviceId(),
                        _request.parmSubmissionId(), supervisor);
                }
                else if (journalTrans.RecId)
                {
                    journalTrans.Counted = e.currentValue();
                    journalTrans.modifiedField(fieldNum(InventJournalTrans, Counted));
                    journalTrans.update();
                }
                accepted++;
            }

            select count(RecId) from journalTrans where journalTrans.JournalId == journalTable.JournalId;
            journalTable.NumOfLines = int642int(journalTrans.RecId);
            journalTable.update();
            ttscommit;
        }
        catch (Exception::Error)
        {
            response.parmErrorCode('REJECTED');
            response.parmMessage(infolog.text(infologLine()));
            return response;
        }

        HSMobileOpsCountAssortment::flagUnexpected(_request.parmJournalId());
        if (HSMobileOpsCountWallToWall::isWallToWall(_request.parmJournalId()))
        {
            HSMobileOpsCountWallToWall::refreshTasks(_request.parmJournalId());
        }
        response.parmAccepted(accepted);
        if (emptyRefusals)
        {
            response.parmErrorCode('EMPTY_REFUSED');
            response.parmMessage(strFmt('%1 unexpected item(s) added. %2', accepted, emptyRefusals));
            return response;
        }
        if (notPlaced)
        {
            // Kept on the device as not sent, so the counter sees which and can send again.
            response.parmErrorCode('NOT_PLACED');
            response.parmMessage(strFmt('%1 added to the journal; %2 could not be (%3) - items without their configuration, size, colour or style, or not known to D365FO, need to be added in D365FO',
                accepted, notPlaced, skipped));
            return response;
        }
        response.parmSuccess(true);
        response.parmMessage(strFmt('%1 unexpected item(s) added to the journal', accepted));
    }
    return response;
}

/// <summary>The locations a counter found empty. Answers the refusals, if any.</summary>
private static str confirmEmptyLocations(HSMobileOpsCountExceptionsRequest _request)
{
    Newtonsoft.Json.Linq.JArray  jArray;
    Newtonsoft.Json.Linq.JObject jRow;
    str                          refusals;
    str                          refusal;
    int                          i;

    try
    {
        jArray = Newtonsoft.Json.Linq.JArray::Parse(_request.parmEmptyLocationsJson());
    }
    catch (Exception::CLRError)
    {
        return 'The empty locations could not be read.';
    }
    for (i = 0; jArray != null && i < jArray.get_Count(); i++)
    {
        jRow = jArray.get_Item(i);
        refusal = HSMobileOpsCountWallToWall::confirmEmpty(_request.parmJournalId(),
            HSMobileOpsCountTaskService::jsonStr(jRow, 'LocationId'), _request.parmUserId());
        if (refusal)
        {
            refusals += (refusals ? ' ' : '') + refusal;
        }
    }
    return refusals;
}

/// <summary>
/// Wall-to-wall: a counter says a location is done, after its counts are in. Refused while
/// any line there has no count.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountLocationResponse completeLocation(HSMobileOpsCountLocationRequest _request)
{
    return HSMobileOpsCountTaskService::locationAction(_request, false);
}

/// <summary>
/// Wall-to-wall: a counter says a location holds nothing. Its lines settle at 0 and it is
/// complete. Refused once anyone has counted a line there.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountLocationResponse confirmLocationEmpty(HSMobileOpsCountLocationRequest _request)
{
    return HSMobileOpsCountTaskService::locationAction(_request, true);
}

private static HSMobileOpsCountLocationResponse locationAction(HSMobileOpsCountLocationRequest _request, boolean _empty)
{
    HSMobileOpsCountLocationResponse response = new HSMobileOpsCountLocationResponse();
    HSMobileOpsUser                  user;
    str                              refusal;

    response.parmSuccess(false);
    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId() || !_request.parmUserId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        user = HSMobileOpsUser::find(_request.parmUserId());
        if (!user.RecId || !user.IsActive)
        {
            response.parmErrorCode('NOT_ALLOWED');
            return response;
        }
        if (!HSMobileOpsCountWallToWall::isWallToWall(_request.parmJournalId()))
        {
            response.parmErrorCode('NOT_WALL_TO_WALL');
            response.parmMessage(strFmt('%1 is not a wall-to-wall count.', _request.parmJournalId()));
            return response;
        }
        refusal = _empty
            ? HSMobileOpsCountWallToWall::confirmEmpty(_request.parmJournalId(), _request.parmLocationId(), _request.parmUserId())
            : HSMobileOpsCountWallToWall::completeLocation(_request.parmJournalId(), _request.parmLocationId(), _request.parmUserId());
        response.parmOpenTasks(HSMobileOpsCountTask::openTasks(_request.parmJournalId()));
        if (refusal)
        {
            response.parmErrorCode('LOCATION_REFUSED');
            response.parmMessage(refusal);
            return response;
        }
        response.parmSuccess(true);
        response.parmMessage(strFmt('%1 is complete. %2 location(s) left.', _request.parmLocationId(), response.parmOpenTasks()));
    }
    return response;
}

/// <summary>
/// Is the warehouse frozen for a wall-to-wall count? Asked by the handheld's movement screens
/// before work starts; the posting itself refuses too, whatever they were told.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsFreezeStatusResponse getFreezeStatus(HSMobileOpsFreezeStatusRequest _request)
{
    HSMobileOpsFreezeStatusResponse response = new HSMobileOpsFreezeStatusResponse();
    HSMobileOpsWarehouseFreeze      freeze;

    response.parmSuccess(false);
    if (!_request || !_request.parmDataAreaId() || !_request.parmWarehouseId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    changecompany (_request.parmDataAreaId())
    {
        freeze = HSMobileOpsWarehouseFreeze::findActive(_request.parmWarehouseId());
        response.parmFrozen(freeze.RecId != 0);
        if (freeze.RecId)
        {
            response.parmJournalId(freeze.JournalId);
            response.parmStatus(enum2Str(freeze.Status));
            response.parmFrozenSinceUtc(freeze.StartedUtc);
            response.parmMessage(HSMobileOpsWarehouseFreeze::frozenMessage(_request.parmWarehouseId()));
        }
        response.parmSuccess(true);
    }
    return response;
}

/// <summary>
/// Used by reportDiscrepancy. There is no on-demand spot count any more (user, 8 Nov: it is
/// the same as Store count).
///
/// A counting journal for one item, one location, or one item in one location, in a
/// warehouse: a line per on-hand dimension there, with D365FO's on-hand quantity. An item
/// named at a location where D365FO has none of it still gets its line (on-hand 0), so stock
/// found where the system has none can be counted in. Counted in the app like any other
/// counting journal - it is in the warehouse's journal list.
///
/// Counted starts equal to the on-hand: a line nobody counted posts no adjustment, rather
/// than writing the stock off.
/// </summary>
private static void createSpotJournal(HSMobileOpsCountSpotResponse _response, str _userId, InventLocationId _warehouseId,
    ItemId _itemId, WMSLocationId _locationId, str _purpose)
{
    HSMobileOpsUser     user = HSMobileOpsUser::find(_userId);
    InventJournalName   journalName;
    InventJournalTable  journalTable;
    JournalTableData    journalTableData;
    InventSum           inventSum;
    InventDim           inventDim;
    InventDim           lineDim;
    LineNum             lineNum;

    if (!user.RecId || !user.IsActive)
    {
        _response.parmErrorCode('NOT_ALLOWED');
        _response.parmMessage(strFmt('%1 is not an active mobile user', _userId));
        return;
    }
    if (!InventLocation::find(_warehouseId).RecId)
    {
        _response.parmErrorCode('INVALID_REQUEST');
        _response.parmMessage(strFmt('No warehouse %1', _warehouseId));
        return;
    }
    if (_itemId && !InventTable::find(_itemId).RecId)
    {
        _response.parmErrorCode('UNKNOWN_ITEM');
        _response.parmMessage(strFmt('No item %1', _itemId));
        return;
    }
    if (_locationId && !WMSLocation::find(_locationId, _warehouseId).RecId)
    {
        _response.parmErrorCode('UNKNOWN_LOCATION');
        _response.parmMessage(strFmt('No location %1 in warehouse %2', _locationId, _warehouseId));
        return;
    }

    // A spot count is a few lines, not a stock take: a whole bulk location without an item
    // (AAC: 3,011 stock lines) would be one enormous journal no worker can count, and a
    // heavy insert on D365FO. Counted first - nothing is created when it is too many.
    select count(RecId) from inventSum
        where (!_itemId || inventSum.ItemId == _itemId)
           && inventSum.Closed         == NoYes::No
           && inventSum.PhysicalInvent != 0
        exists join inventDim
            where inventDim.inventDimId      == inventSum.InventDimId
               && inventDim.InventLocationId == _warehouseId
               && (!_locationId || inventDim.wMSLocationId == _locationId);
    if (inventSum.RecId > HSMobileOpsCountTaskService::maxSpotLines())
    {
        _response.parmErrorCode('TOO_MANY_LINES');
        _response.parmMessage(strFmt('%1 holds %2 stock lines - too many for a spot count. Name the item to count%3',
            _locationId ? _locationId : _warehouseId, inventSum.RecId, _locationId ? '' : ', or a location'));
        return;
    }
    inventSum.clear();

    select firstonly journalName
        where journalName.JournalType == InventJournalType::Count;
    if (!journalName.RecId)
    {
        _response.parmErrorCode('NO_JOURNAL_NAME');
        _response.parmMessage('D365FO has no counting journal name set up');
        return;
    }

    ttsbegin;
    journalTable.clear();
    journalTable.initValue();
    journalTableData = JournalTableData::newTable(journalTable);
    journalTable.JournalId = journalTableData.nextJournalId();
    journalTableData.initFromJournalName(journalName);
    journalTable.Description = subStr(strFmt('%1 - %2%3%4 by %5', _purpose, _itemId,
        (_itemId && _locationId) ? ' at ' : '', _locationId, _userId), 1, 60);
    journalTable.insert();

    while select inventSum
        where (!_itemId || inventSum.ItemId == _itemId)
           && inventSum.Closed         == NoYes::No
           && inventSum.PhysicalInvent != 0
        join inventDim
            where inventDim.inventDimId      == inventSum.InventDimId
               && inventDim.InventLocationId == _warehouseId
               && (!_locationId || inventDim.wMSLocationId == _locationId)
    {
        lineNum++;
        HSMobileOpsCountTaskService::addSpotLine(journalTable, lineNum, inventSum.ItemId, inventSum.InventDimId, inventSum.PhysicalInvent);
    }

    if (!lineNum && _itemId && _locationId)
    {
        lineDim.clear();
        lineDim.InventSiteId     = InventLocation::find(_warehouseId).InventSiteId;
        lineDim.InventLocationId = _warehouseId;
        lineDim.wMSLocationId    = _locationId;
        lineDim = InventDim::findOrCreate(lineDim);
        lineNum++;
        HSMobileOpsCountTaskService::addSpotLine(journalTable, lineNum, _itemId, lineDim.inventDimId, 0);
    }

    if (!lineNum)
    {
        ttsabort;
        _response.parmErrorCode('NOTHING_TO_COUNT');
        _response.parmMessage(strFmt('D365FO has no stock of %1 in %2 - name an item and a location to count one in',
            _itemId ? _itemId : 'anything', _locationId ? _locationId : _warehouseId));
        return;
    }

    journalTable.selectForUpdate(true);
    journalTable.NumOfLines = lineNum;
    journalTable.update();
    ttscommit;

    _response.parmSuccess(true);
    _response.parmJournalId(journalTable.JournalId);
    _response.parmJournalNameId(journalTable.JournalNameId);
    _response.parmMessage(strFmt('%1 - %2 lines to count', journalTable.JournalId, lineNum));
}

/// <summary>The most lines a spot count (or a discrepancy's count) may have.</summary>
private static int maxSpotLines()
{
    return 200;
}

private static void addSpotLine(InventJournalTable _journalTable, LineNum _lineNum, ItemId _itemId,
    InventDimId _inventDimId, InventQty _onHand)
{
    InventJournalTrans journalTrans;

    journalTrans.clear();
    journalTrans.initValue();
    journalTrans.initFromInventJournalTable(_journalTable);
    journalTrans.LineNum      = _lineNum;
    journalTrans.TransDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    journalTrans.ItemId       = _itemId;
    journalTrans.initFromInventTable(InventTable::find(_itemId));
    journalTrans.InventDimId  = _inventDimId;
    journalTrans.InventOnHand = _onHand;
    journalTrans.Counted      = _onHand;
    journalTrans.Qty          = 0;
    journalTrans.insert();
}

/// <summary>
/// After a pick or putaway: should this spot be counted now? Eligible false means show
/// nothing. Never an error for "no" - the app calls this often and quietly.
/// </summary>
public HSMobileOpsCountOpportunityResponse getOpportunityCount(HSMobileOpsCountOpportunityRequest _request)
{
    HSMobileOpsCountOpportunityResponse response = new HSMobileOpsCountOpportunityResponse();

    response.parmSuccess(false);
    response.parmEligible(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmLocationId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // TODO (X++ owner): decide eligibility (e.g. location near empty after the pick, not
    // counted recently, under a daily cap); when eligible, create or find a one-line
    // OPPORTUNITY journal and return it with its line (blind - no quantities).
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// A picker reports a discrepancy at a location. The server decides whether it becomes a
/// TRIGGERED count.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountDiscrepancyResponse reportDiscrepancy(HSMobileOpsCountDiscrepancyRequest _request)
{
    HSMobileOpsCountDiscrepancyResponse response = new HSMobileOpsCountDiscrepancyResponse();

    response.parmSuccess(false);

    if (!_request || !_request.parmDataAreaId() || !_request.parmLocationId() || !_request.parmReason()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // Every report becomes a count of that spot: a counting journal for the location (and the
    // item, when one was named), described with who reported what - the counting supervisor
    // sees the reason on the journal.
    changecompany (_request.parmDataAreaId())
    {
        HSMobileOpsCountSpotResponse spot = new HSMobileOpsCountSpotResponse();
        try
        {
            HSMobileOpsCountTaskService::createSpotJournal(spot, _request.parmUserId(), _request.parmWarehouseId(),
                _request.parmItemNumber(), _request.parmLocationId(),
                strFmt('Discrepancy %1%2', _request.parmReason(), _request.parmNote() ? ': ' + _request.parmNote() : ''));
        }
        catch (Exception::Error)
        {
            spot.parmErrorCode('FAILED');
            spot.parmMessage(infolog.text(infologLine()));
        }
        response.parmSuccess(spot.parmSuccess());
        response.parmErrorCode(spot.parmErrorCode());
        response.parmMessage(spot.parmMessage());
        response.parmTriggeredJournalId(spot.parmJournalId());
    }
    return response;
}

/// <summary>
/// What kind of counter a user is. The app hides screens from this; every counting service
/// applies the same rules itself.
/// </summary>
public HSMobileOpsCountProfileResponse getCounterProfile(HSMobileOpsCountProfileRequest _request)
{
    HSMobileOpsCountProfileResponse response = new HSMobileOpsCountProfileResponse();
    HSMobileOpsUser                 user;

    response.parmSuccess(false);

    if (!_request || !_request.parmUserId() || !_request.parmDataAreaId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // HSMobileOpsUser is per company - looked up in the request's company, as signIn does.
    changecompany (_request.parmDataAreaId())
    {
        user = HSMobileOpsUser::find(_request.parmUserId());
    }
    if (!user.RecId || !user.IsActive)
    {
        response.parmErrorCode('USER_NOT_FOUND');
        return response;
    }

    response.parmIsExternalCounter(user.IsExternalCounter == NoYes::Yes);
    response.parmCounterTeam(user.CounterTeam);
    // An external counter never gets supervisor rights, whatever else is ticked.
    response.parmIsCycleCountSupervisor(user.IsCycleCountSupervisor == NoYes::Yes && user.IsExternalCounter == NoYes::No);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// Location type, owner and verify-only per line. A line not returned is PHYSICAL, own stock,
/// counted normally - so the empty answer below is a safe default.
/// </summary>
public HSMobileOpsCountLineAttributesResponse getLineAttributes(HSMobileOpsCountLineAttributesRequest _request)
{
    HSMobileOpsCountLineAttributesResponse response = new HSMobileOpsCountLineAttributesResponse();

    response.parmSuccess(false);
    response.parmLines(new List(Types::Class));

    if (!_request || !_request.parmDataAreaId() || !_request.parmJournalId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // TODO (X++ owner): per line, the location's type (VIRTUAL, CONSIGNMENT_OWN,
    // CONSIGNMENT_VENDOR, TRANSIT), the stock owner for consignment / third-party stock, and
    // whether it is verify-only (confirmed present, not counted). Which location types appear
    // in a journal at all is decided when the journal is generated.
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// HSMobileOpsLineClaim.ProcessType of a counting journal claim.
/// </summary>
public static str claimProcess()
{
    return 'COUNT';
}

/// <summary>
/// How long a claim lives past its last heartbeat. Twenty minutes: several missed two-minute
/// heartbeats, and longer than the 15-minute background check-in the app falls back to when
/// its process is stopped - so a pocketed handheld keeps its journal.
/// </summary>
public static int claimTtlSeconds()
{
    return 20 * 60;
}

/// <summary>
/// How often the app is asked to heartbeat a claim.
/// </summary>
public static int claimHeartbeatSeconds()
{
    return 120;
}

/// <summary>
/// Whether the claim belongs to this user on this device. Both must match: the same login
/// on a second handheld is someone else.
/// </summary>
public static boolean isClaimHolder(HSMobileOpsLineClaim _claim, str _userId, str _deviceId)
{
    return _userId && _deviceId
        && strUpr(_claim.ClaimedByUserName) == strUpr(_userId)
        && _claim.DeviceId == _deviceId;
}

/// <summary>
/// Who holds a claim, as the app shows it: "Asha Rao (001)", plus "on another device" when
/// the holder is on a different handheld from the one asking.
/// </summary>
public static str claimedByLabel(HSMobileOpsLineClaim _claim, str _deviceId = '')
{
    str label = _claim.ClaimedByDisplayName
        ? strFmt('%1 (%2)', _claim.ClaimedByDisplayName, _claim.ClaimedByUserName)
        : _claim.ClaimedByUserName;

    if (_deviceId && _claim.DeviceId != _deviceId)
    {
        label += ' on another device';
    }
    return label;
}

/// <summary>
/// The live claim on a journal, or an empty buffer.
/// </summary>
public static HSMobileOpsLineClaim activeClaim(DataAreaId _company, InventJournalId _journalId)
{
    HSMobileOpsLineClaim claim;

    changecompany (_company)
    {
        claim = HSMobileOpsLineClaim::findActive(HSMobileOpsCountTaskService::claimProcess(), _journalId, 0);
    }
    return claim;
}

/// <summary>
/// Who else holds a live claim on the journal - the label of a claim that is not this user
/// on this device - or '' when the counts may go in.
/// </summary>
public static str otherClaimHolder(DataAreaId _company, InventJournalId _journalId, str _userId, str _deviceId)
{
    HSMobileOpsLineClaim claim = HSMobileOpsCountTaskService::activeClaim(_company, _journalId);

    if (claim.RecId && !HSMobileOpsCountTaskService::isClaimHolder(claim, _userId, _deviceId))
    {
        return HSMobileOpsCountTaskService::claimedByLabel(claim, _deviceId);
    }
    return '';
}

/// <summary>
/// Fills a successful claim or heartbeat answer.
/// </summary>
private static void grantClaim(HSMobileOpsCountClaimResponse _response, HSMobileOpsLineClaim _claim)
{
    _response.parmSuccess(true);
    _response.parmErrorCode('');
    _response.parmClaimToken(int642Str(_claim.RecId));
    _response.parmClaimedBy(_claim.ClaimedByDisplayName ? _claim.ClaimedByDisplayName : _claim.ClaimedByUserName);
    _response.parmExpiresUtc(_claim.ClaimExpiresUtc);
    _response.parmHeartbeatSeconds(HSMobileOpsCountTaskService::claimHeartbeatSeconds());
}

/// <summary>
/// OPEN / POSTED / NOT_FOUND for one counting journal. Shared by every operation here and by
/// HSMobileOpsCountingService::importCounts.
/// </summary>
public static str journalState(DataAreaId _company, InventJournalId _journalId)
{
    InventJournalTable inventJournalTable;

    changecompany (_company)
    {
        select firstOnly RecId, Posted, JournalType from inventJournalTable
            where inventJournalTable.JournalId == _journalId;
    }

    if (!inventJournalTable.RecId || inventJournalTable.JournalType != InventJournalType::Count)
    {
        return HSMobileOpsCountTaskService::stateNotFound();
    }

    return inventJournalTable.Posted == NoYes::Yes
        ? HSMobileOpsCountTaskService::statePosted()
        : HSMobileOpsCountTaskService::stateOpen();
}

public static str stateOpen()
{
    return 'OPEN';
}

public static str statePosted()
{
    return 'POSTED';
}

public static str stateNotFound()
{
    return 'NOT_FOUND';
}

/// <summary>
/// Ceiling for DIRECT mode. Anything bigger is a DMF journal.
/// </summary>
private static int maxDirectLines()
{
    return 500;
}
